def code_block(md, lang):
    m = re.search('```' + lang + r'\n(.*?)\n```', (REF / md).read_text(encoding='utf-8'), re.S)
    return m.group(1)


def placeholder(path, w, h):
    from PIL import Image, ImageDraw, ImageFont
    im = Image.new('RGB', (w, h), (236, 238, 241))
    d = ImageDraw.Draw(im)
    for x in range(0, w, 100):
        d.line([(x, 0), (x, h)], fill=(222, 225, 229))
    for y in range(0, h, 100):
        d.line([(0, y), (w, y)], fill=(222, 225, 229))
    font = None
    for f in ['/System/Library/Fonts/PingFang.ttc', '/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc', 'C:/Windows/Fonts/msyh.ttc']:
        try:
            font = ImageFont.truetype(f, max(28, w // 30)); break
        except Exception:
            pass
    d.text((40, 40), '示例截图 ' + path.name + '（换成自己的截图）', fill=(120, 126, 135), font=font)
    im.save(path)


def main():
    args = [a for a in sys.argv[1:] if not a.startswith('--')]
    if not args:
        sys.exit('用法：python3 example_project.py 目标目录 [--截图 真实截图文件夹]')
    d = Path(args[0]).resolve()
    shots = Path(args[1]).resolve() if '--截图' in sys.argv and len(args) > 1 else None
    (d / 'assets').mkdir(parents=True, exist_ok=True)
    (d / 'work').mkdir(exist_ok=True)
    (d / 'project.json').write_text(json.dumps({'栏目标签': '老板问答', '系列名': 'WorkBuddy 七个词', '风格': 'qingshuang', '画幅': '横', '录音文件': ''},
                                               ensure_ascii=False, indent=1), encoding='utf-8')
    (d / 'script.txt').write_text(code_block('示例口播稿.md', 'text') + '\n', encoding='utf-8')
    (d / 'scenes.html').write_text(code_block('示例画面.md', 'html') + '\n', encoding='utf-8')
    (d / 'work' / 'timeline.json').write_text(json.dumps(TIMELINE, ensure_ascii=False), encoding='utf-8')
    for name, (w, h) in SIZES.items():
        if shots and (shots / name).exists():
            shutil.copy(shots / name, d / 'assets' / name)
        elif not (d / 'assets' / name).exists():
            placeholder(d / 'assets' / name, w, h)
    print(f'示例项目放好了：{d}\n接着可以运行：python3 {HERE / "render.py"} {d} 检查')


if __name__ == '__main__':
    main()
